async function themeRows(theme) {
	const { byId } = await data();
	const lists = (await import("./lists-CPyNRZJ_.mjs")).default ?? {};
	const out = [];
	for (const [id, i] of lists[theme] ?? []) {
		const c = byId.get(id);
		const h = (c ? await cityData(id) : null)?.hotels[i];
		if (c && h) out.push({
			c,
			h
		});
	}
	return out;
}
